    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0)
  ); INSERT INTO projects (name) VALUES ('Legacy');`);
  legacy.close();

const migrated = await (await fetch(base)).text();
