await stop();
const fixture = new DatabaseSync(join(directory, 'db.sqlite'));
fixture.exec("DELETE FROM projects; DELETE FROM sqlite_sequence WHERE name = 'projects'");
fixture.close();
await start();
const initial = await (await fetch(base)).text();

